import config from '../config/youtube';

class YouTubeService {
  constructor() {
    this.apiKey = config.youtube.apiKey;
    this.channelId = config.youtube.channelId;
    this.baseURL = 'https://www.googleapis.com/youtube/v3';
  }

  async makeRequest(endpoint, params = {}) {
    try {
      const queryParams = new URLSearchParams({
        key: this.apiKey,
        ...params
      });

      console.log('🌐 Fazendo requisição para:', `${this.baseURL}/${endpoint}?${queryParams}`);
      
      const response = await fetch(`${this.baseURL}/${endpoint}?${queryParams}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      console.log('✅ Resposta da API:', data);
      return data;

    } catch (error) {
      console.error('❌ Erro na requisição YouTube:', error);
      throw error;
    }
  }

  // Buscar transmissões ao vivo ATIVAS
  async getLiveStreams() {
    try {
      console.log('🔴 Buscando transmissões ao vivo ATIVAS...');
      
      const data = await this.makeRequest('search', {
        channelId: this.channelId,
        eventType: 'live',
        type: 'video',
        maxResults: 1,
        order: 'date',
        part: 'snippet'
      });

      console.log('📊 Resultado live ativa:', data);
      
      if (data.items && data.items.length > 0) {
        const liveStream = data.items[0];
        console.log('🎯 Live ATIVA encontrada:', liveStream.snippet.title);
        return data;
      } else {
        console.log('📡 Nenhuma live ATIVA no momento');
        return { items: [] };
      }
    } catch (error) {
      console.error('❌ Erro ao buscar lives ativas:', error);
      return { items: [] };
    }
  }

  // Buscar VÍDEOS DO CANAL (simplificado)
  async getRecentVideos(limit = 6) {
    try {
      console.log('📹 Buscando VÍDEOS do canal...');
      
      // Busca direto os vídeos do canal
      const searchData = await this.makeRequest('search', {
        channelId: this.channelId,
        type: 'video',
        maxResults: limit,
        order: 'date',
        part: 'snippet'
      });

      console.log('📊 Resultado busca vídeos:', searchData);

      if (!searchData.items || searchData.items.length === 0) {
        console.log('⚠️ Nenhum vídeo encontrado via API, usando fallback');
        return this.getFallbackVideos(limit);
      }

      // Para cada vídeo, busca detalhes completos
      const videosWithDetails = await Promise.all(
        searchData.items.map(async (item) => {
          try {
            const videoDetails = await this.getVideoDetails(item.id.videoId);
            return {
              id: item.id.videoId,
              videoId: item.id.videoId,
              titulo: item.snippet.title,
              descricao: item.snippet.description,
              thumbnail: item.snippet.thumbnails.medium?.url || item.snippet.thumbnails.default?.url,
              data: new Date(item.snippet.publishedAt).toLocaleDateString('pt-BR'),
              duracao: videoDetails.duration,
              duracaoLegivel: videoDetails.durationLegible,
              visualizacoes: videoDetails.viewCount,
              foiLive: videoDetails.wasLive
            };
          } catch (error) {
            console.error('❌ Erro ao buscar detalhes do vídeo:', error);
            return this.createBasicVideo(item);
          }
        })
      );

      console.log('✅ Vídeos processados com sucesso:', videosWithDetails);
      return videosWithDetails;

    } catch (error) {
      console.error('❌ Erro geral ao buscar vídeos:', error);
      return this.getFallbackVideos(limit);
    }
  }

  // Buscar detalhes específicos do vídeo
  async getVideoDetails(videoId) {
    try {
      console.log('🔍 Buscando detalhes do vídeo:', videoId);
      
      const data = await this.makeRequest('videos', {
        id: videoId,
        part: 'contentDetails,statistics,liveStreamingDetails,snippet'
      });

      if (!data.items || data.items.length === 0) {
        return {
          duration: 'PT1H0M',
          durationLegible: '1:00:00',
          viewCount: '0',
          wasLive: false
        };
      }

      const video = data.items[0];
      const durationLegible = this.formatDuration(video.contentDetails?.duration);
      
      // Verifica se era uma live (tem detalhes de transmissão OU título indica live)
      const wasLive = !!video.liveStreamingDetails || 
                     video.snippet?.title?.toLowerCase().includes('live') ||
                     video.snippet?.title?.toLowerCase().includes('ao vivo');

      return {
        duration: video.contentDetails?.duration || 'PT1H0M',
        durationLegible: durationLegible,
        viewCount: video.statistics?.viewCount || '0',
        wasLive: wasLive
      };

    } catch (error) {
      console.error('❌ Erro nos detalhes do vídeo:', error);
      return {
        duration: 'PT1H0M',
        durationLegible: '1:00:00', 
        viewCount: '0',
        wasLive: false
      };
    }
  }

  // Criar vídeo básico (fallback para erro nos detalhes)
  createBasicVideo(item) {
    return {
      id: item.id.videoId,
      videoId: item.id.videoId,
      titulo: item.snippet.title,
      descricao: item.snippet.description,
      thumbnail: item.snippet.thumbnails.medium?.url || item.snippet.thumbnails.default?.url,
      data: new Date(item.snippet.publishedAt).toLocaleDateString('pt-BR'),
      duracao: 'PT1H0M',
      duracaoLegivel: '1:00:00',
      visualizacoes: '0',
      foiLive: false
    };
  }

  // Formatar duração ISO 8601 para legível
  formatDuration(duration) {
    if (!duration || duration === 'P0D') return '0:00';
    
    const match = duration.match(/PT(\d+H)?(\d+M)?(\d+S)?/);
    if (!match) return duration;

    const hours = (match[1] || '').replace('H', '');
    const minutes = (match[2] || '').replace('M', '');
    const seconds = (match[3] || '').replace('S', '');

    if (hours) {
      return `${hours}:${minutes.padStart(2, '0')}:${seconds.padStart(2, '0')}`;
    }
    return `${minutes || '0'}:${seconds.padStart(2, '0')}`;
  }

  // ========== FALLBACK DATA ==========
  getFallbackVideos(limit = 6) {
    console.log('🔄 Usando vídeos fallback');
    
    const fallbackVideos = [
      {
        id: 'video1',
        titulo: 'Congresso do Círculo de Oração - Colunas de Fé',
        data: '25 Jul 2025',
        videoId: 'rT8YqGItaR0',
        thumbnail: 'https://img.youtube.com/vi/rT8YqGItaR0/hqdefault.jpg',
        duracao: '2:07:55',
        visualizacoes: '131',
        duracaoLegivel: '2:07:55',
        foiLive: true
      },
      {
        id: 'video2', 
        titulo: 'Congresso de Jovens (Dia 02)',
        data: '24 Mai 2025',
        videoId: 'QQc8996nOvM',
        thumbnail: 'https://img.youtube.com/vi/QQc8996nOvM/hqdefault.jpg',
        duracao: '2:52:45',
        visualizacoes: '131',
        duracaoLegivel: '2:52:45',
        foiLive: true
      },
      {
        id: 'video3',
        titulo: 'Culto de Ação de Graça',
        data: '16 Ago 2025',
        videoId: '1U0T3ZFEI3w',
        thumbnail: 'https://img.youtube.com/vi/1U0T3ZFEI3w/hqdefault.jpg',
        duracao: '3:31:40',
        visualizacoes: '98',
        duracaoLegivel: '3:31:40',
        foiLive: true
      },
      {
        id: 'video4',
        titulo: 'Congresso Infantil - Dia 02',
        data: '21 Jun 2025',
        videoId: 'WFS8EDhs9iw',
        thumbnail: 'https://img.youtube.com/vi/WFS8EDhs9iw/hqdefault.jpg',
        duracao: '2:13:30',
        visualizacoes: '91',
        duracaoLegivel: '2:13:30',
        foiLive: true
      },
      {
        id: 'video5',
        titulo: '14° Aniversário da Igreja | Dia 01',
        data: '16 Nov 2024',
        videoId: '4vmylFlIL20',
        thumbnail: 'https://img.youtube.com/vi/4vmylFlIL20/hqdefault.jpg',
        duracao: '2:35:25',
        visualizacoes: '77',
        duracaoLegivel: '2:35:25',
        wasLive: true
      },
      {
        id: 'video6',
        titulo: 'Culto de Missão',
        data: '14 Set 2025',
        videoId: 'KOaB1TWnT2w',
        thumbnail: 'https://img.youtube.com/vi/KOaB1TWnT2w/hqdefault.jpg',
        duracao: '2:26:40',
        visualizacoes: '94',
        duracaoLegivel: '2:26:40',
        foiLive: true
      }
    ];
    return fallbackVideos.slice(0, limit);
  }
}

export default new YouTubeService();
